#define N_GROUPS 2
regmatch_t pmatch[N_GROUPS];
char *source = "Version: 1.5.0";

// After successful regexec():
// pmatch[1].rm_so, pmatch[1].rm_eo holds Group 1 offsets

int group_idx = 1;
long start_offset = pmatch[group_idx].rm_so;
long end_offset = pmatch[group_idx].rm_eo;

// Subexpression length calculation
size_t len = end_offset - start_offset;

// Pointer arithmetic to find start of match
const char *match_start_ptr = source + start_offset;

// Extraction using length and pointer
char submatch_buffer[32];
strncpy(submatch_buffer, match_start_ptr, len);
submatch_buffer[len] = '\0'; // Null-terminate
// Accessing source[pmatch[1].rm_so] gives the first character
// Accessing source[pmatch[1].rm_eo - 1] gives the last character
// The full match is source[pmatch[0].rm_so ... pmatch[0].rm_eo - 1]
